public class Main {
    static int process(int[] arr) {
        int sum = 0;
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] % 2 == 0) {
                sum += arr[i];
            } else {
                sum -= arr[i];
            }
        }
        return sum;
    }

    public static void main(String[] args) {
        int[] numbers = {1, 2, 3, 4, 5, 6};
        int result = process(numbers);
        System.out.println("result: " + result);

        int total = 0;
        for (int n : numbers) {
            total += n;
        }
        System.out.println("total: " + total);
    }
}

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)


def process(nums):
    result = []
    for n in nums:
        if n % 2 == 0:
            result.append(factorial(n))
        else:
            result.append(n * n)
    return result


data = [1, 2, 3, 4, 5]
output = process(data)
print(output)

total = sum(output)
print(total)

